def UTwoFieldMeanStatement : Prop :=
  ∀ fields : Fin 2 → Vec3, (∀ j, normSq (fields j) ≤ 1) →
    normSq (localMean .U fields) ≤ (1/2 : ℝ)^2

def SpecialBernsteinSoundnessStatement : Prop :=
  SpecialCoordinateEstimateStatement → SingleSitePositiveStatement → BallAffinityStatement →
    ∀ r ∈ specialRows, specialCheck r = true → SpecialMeanBound r

def LocalTableSoundnessStatement : Prop :=
  ∀ s : Site, ∀ t : Lookup, localTableCheck s t = true →
    ∀ i < (localTable s).length, t.get i = (localTable s).getD i .zero

def PackedReconstructionSoundnessStatement : Prop :=
  LocalTableSoundnessStatement → ∀ c ∈ matrixCases,
    matrixCaseCheck c = true → Reconstructed c

def GramCheckerRefinementStatement : Prop :=
  ∀ w : GramWitness, gramCheck w = true →
    AKLT.Gen.Gram.checker w.matrix w.factor 1 w.denominator w.scale = true

def GramFormTransportStatement : Prop :=
  GramCheckerRefinementStatement → ∀ c ∈ matrixCases,
    matrixCaseCheck c = true → (witnessMatrix c).PosDef

def CentralScalingStatement : Prop :=
  ∀ c ∈ matrixCases, matrixCaseCheck c = true →
    Reconstructed c → (witnessMatrix c).PosDef → (centralForm c).PosDef

def ForestHermitianStatement : Prop :=
  ∀ c ∈ matrixCases,
    (forestOperator (models.getD c.index ⟨false,[]⟩) c.inversion).IsHermitian

def UpperDTwoBondStatement : Prop :=
  ∀ a b : Vec3,
    siteFunctional .D (fun n => (1+dot n a)*(1+dot n b)) = 1+dot a b/5

def ArrivalOneAliveStatement : Prop :=
  ∀ μ b : Vec3, siteFunctional .D (fun n => (1+dot μ n)*(1+dot n b)) =
    1+dot ((1/5 : ℝ) • μ) b

def EmptyModelEvaluationStatement : Prop :=
  ∀ m : Model, m.paths = [] → ∀ a : Assignment,
    Zcur m a = 1 ∧ Znext m a = 1
